public class MainActivity extends Activity {
    private static final int NAVY=Color.rgb(24,52,92), BLUE=Color.rgb(35,120,225), BG=Color.rgb(247,249,252), TEXT=Color.rgb(28,38,52), MUTED=Color.rgb(100,112,128), GREEN=Color.rgb(35,155,105), ORANGE=Color.rgb(239,145,45);
    private static final String[] TYPES={"Todas","Decesos","Vida","Hogar","Auto","Salud","Accidentes","Otros"};
    private static final int PBKDF2_ITERATIONS=120000;
    private SharedPreferences prefs; private LinearLayout content; private String currentUser; private final Executor executor=Executors.newSingleThreadExecutor();
    private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("rgapro_local",MODE_PRIVATE);migrateLegacy();if(!hasPin())createFirstUser();else access();}
    private boolean hasPin(){return prefs.contains("pin_hash")&&prefs.contains("pin_salt");}
    private EditText input(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setTextSize(15);return e;}
    private EditText pin(String h){EditText e=input(h);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);return e;}
    private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView label(String s,float z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(bold?Typeface.DEFAULT_BOLD:Typeface.DEFAULT);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private GradientDrawable bg(int color,int radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(radius));return g;}
    private Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);b.setMinHeight(0);b.setTextColor(TEXT);b.setPadding(dp(12),0,dp(12),0);GradientDrawable g=bg(Color.WHITE,14);g.setStroke(dp(1),Color.rgb(224,229,237));b.setBackground(g);return b;}
    private Button primary(String s){Button b=button(s);b.setTextColor(Color.WHITE);b.setTypeface(Typeface.DEFAULT_BOLD);b.setBackground(bg(BLUE,14));return b;}
    private JSONObject users(){try{return new JSONObject(prefs.getString("users_json","{}"));}catch(Exception e){return new JSONObject();}}
    private void saveUsers(JSONObject u){prefs.edit().putString("users_json",u.toString()).apply();}
    private void migrateLegacy(){try{JSONObject u=users();if(u.length()==0&&prefs.getStringSet("policies",null)!=null){JSONObject o=new JSONObject();o.put("pin_hash",prefs.getString("pin_hash",""));o.put("pin_salt",prefs.getString("pin_salt",""));JSONArray a=new JSONArray();for(String s:prefs.getStringSet("policies",new HashSet<>()))a.put(s);o.put("policies",a);u.put("Administrador",o);saveUsers(u);prefs.edit().remove("policies").apply();}else if(u.length()==0&&hasPin()){JSONObject o=new JSONObject();o.put("pin_hash",prefs.getString("pin_hash",""));o.put("pin_salt",prefs.getString("pin_salt",""));o.put("policies",new JSONArray());u.put("Administrador",o);saveUsers(u);}}catch(Exception ignored){}}
    private void createFirstUser(){final EditText name=input("Nombre de usuario"),a=pin("Clave de 6 dígitos"),b=pin("Repite la clave");LinearLayout box=vertical();box.setPadding(dp(20),0,dp(20),0);box.addView(name);box.addView(a);box.addView(b);AlertDialog d=new AlertDialog.Builder(this).setTitle("👋 Bienvenido a RgaPro").setMessage("Crea tu usuario. Cada cartera queda separada y privada.").setView(box).setCancelable(false).setPositiveButton("Crear cartera",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String n=name.getText().toString().trim(),p=a.getText().toString();if(n.isEmpty()){name.setError("Indica un nombre");return;}if(!p.matches("\\d{6}")||!p.equals(b.getText().toString())){b.setError("Usa 6 dígitos y repítelos");return;}try{JSONObject u=users(),o=new JSONObject();byte[] s=new byte[16];new SecureRandom().nextBytes(s);o.put("pin_hash",Base64.encodeToString(derive(p,s),Base64.NO_WRAP));o.put("pin_salt",Base64.encodeToString(s,Base64.NO_WRAP));o.put("policies",new JSONArray());u.put(n,o);saveUsers(u);prefs.edit().putString("pin_hash",o.getString("pin_hash")).putString("pin_salt",o.getString("pin_salt")).apply();currentUser=n;d.dismiss();home();}catch(Exception e){Toast.makeText(this,"No se pudo crear el usuario",Toast.LENGTH_LONG).show();}}));d.show();}
    private byte[] derive(String p,byte[] s)throws Exception{PBEKeySpec spec=new PBEKeySpec(p.toCharArray(),s,PBKDF2_ITERATIONS,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
    private boolean verifyUser(String n,String p){try{JSONObject o=users().optJSONObject(n);if(o==null)return false;return MessageDigest.isEqual(Base64.decode(o.optString("pin_hash"),0),derive(p,Base64.decode(o.optString("pin_salt"),0)));}catch(Exception e){return false;}}
    private JSONArray policies(){try{JSONObject o=users().optJSONObject(currentUser);return o==null?new JSONArray():o.optJSONArray("policies");}catch(Exception e){return new JSONArray();}}
    private void savePolicies(JSONArray a){try{JSONObject u=users(),o=u.getJSONObject(currentUser);o.put("policies",a);u.put(currentUser,o);saveUsers(u);}catch(Exception ignored){}}
    private void access(){LinearLayout root=vertical();root.setGravity(Gravity.CENTER);root.setPadding(dp(28),dp(20),dp(28),dp(20));root.setBackgroundColor(BG);TextView logo=label("RgaPro",34,NAVY,true);logo.setGravity(Gravity.CENTER);root.addView(logo,new LinearLayout.LayoutParams(-1,dp(62)));TextView wave=label("Tu cartera, clara y bajo tu control ✨",17,MUTED,false);wave.setGravity(Gravity.CENTER);root.addView(wave,new LinearLayout.LayoutParams(-1,dp(38)));LinearLayout card=vertical();card.setPadding(dp(20),dp(18),dp(20),dp(18));card.setBackground(bg(Color.WHITE,20));TextView title=label("🔐 Acceder",20,TEXT,true);card.addView(title,new LinearLayout.LayoutParams(-1,dp(40)));Spinner us=new Spinner(this);ArrayList<String> names=new ArrayList<>();Iterator<String> it=users().keys();while(it.hasNext())names.add(it.next());Collections.sort(names);us.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));card.addView(us,new LinearLayout.LayoutParams(-1,dp(52)));Button p=primary("Entrar con clave");p.setOnClickListener(v->login(String.valueOf(us.getSelectedItem())));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(52));pp.topMargin=dp(8);card.addView(p,pp);if(Build.VERSION.SDK_INT>=28){Button bio=button("☝ Usar biometría");bio.setOnClickListener(v->{currentUser=String.valueOf(us.getSelectedItem());biometric();});LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(52));bp.topMargin=dp(8);card.addView(bio,bp);}root.addView(card,new LinearLayout.LayoutParams(-1,dp(220)));TextView foot=label("Privacidad por diseño · compartir solo cuando tú quieras",12,MUTED,false);foot.setGravity(Gravity.CENTER);root.addView(foot,new LinearLayout.LayoutParams(-1,dp(55)));setContentView(root);}
    private void login(String user){EditText e=pin("Clave de 6 dígitos");AlertDialog d=new AlertDialog.Builder(this).setTitle("Desbloquear · "+user).setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(verifyUser(user,e.getText().toString())){currentUser=user;d.dismiss();home();}else e.setError("Clave incorrecta");}));d.show();}
    private void biometric(){if(Build.VERSION.SDK_INT<28){login(currentUser);return;}BiometricPrompt p=new BiometricPrompt.Builder(this).setTitle("Acceso a RgaPro").setSubtitle(currentUser).setDescription("Confirma tu identidad con la biometría del dispositivo.").setNegativeButton("Usar clave",executor,(d,w)->runOnUiThread(()->login(currentUser))).build();p.authenticate(null,executor,new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){runOnUiThread(MainActivity.this::home);}public void onAuthenticationError(int c,CharSequence m){runOnUiThread(()->Toast.makeText(MainActivity.this,"Biometría: "+m,Toast.LENGTH_SHORT).show());}});}
    private void topBar(LinearLayout root,String title,String sub){LinearLayout h=vertical();h.setPadding(dp(18),dp(12),dp(18),dp(12));h.setBackground(bg(NAVY,0));LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);Button back=button("‹");back.setTextColor(Color.WHITE);back.setTextSize(28);back.setBackgroundColor(Color.TRANSPARENT);back.setOnClickListener(v->home());line.addView(back,new LinearLayout.LayoutParams(dp(45),dp(50)));line.addView(label(title,22,Color.WHITE,true),new LinearLayout.LayoutParams(0,dp(50),1));h.addView(line);if(sub!=null)h.addView(label(sub,13,Color.rgb(220,230,245),false),new LinearLayout.LayoutParams(-1,dp(26)));root.addView(h);}
    private void page(String title,String sub){LinearLayout root=vertical();root.setBackgroundColor(BG);topBar(root,title,sub);content=vertical();content.setPadding(dp(18),dp(16),dp(18),dp(28));ScrollView sc=new ScrollView(this);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void home(){LinearLayout root=vertical();root.setBackgroundColor(BG);LinearLayout hero=vertical();hero.setPadding(dp(20),dp(18),dp(20),dp(16));hero.setBackground(bg(NAVY,0));TextView t=label("Hola, "+currentUser+" 👋",24,Color.WHITE,true);hero.addView(t,new LinearLayout.LayoutParams(-1,dp(42)));hero.addView(label("Todo lo importante, a un toque.",14,Color.rgb(220,230,245),false),new LinearLayout.LayoutParams(-1,dp(28)));root.addView(hero);ScrollView sc=new ScrollView(this);LinearLayout body=vertical();body.setPadding(dp(18),dp(16),dp(18),dp(30));TextView hint=label("¿Qué quieres hacer hoy?",18,TEXT,true);body.addView(hint,new LinearLayout.LayoutParams(-1,dp(38)));addHome(body,"👥  CLIENTES","Busca por nombre, DNI, teléfono o póliza",v->clients());addHome(body,"📁  PÓLIZAS","Filtra rápidamente por tipo",v->policiesPage());addHome(body,"⏰  VENCIMIENTOS","60 · 45 · 30 · 15 días",v->expiries());addHome(body,"🔐  SEGURIDAD","Usuarios, acceso y privacidad",v->settings());Button lock=button("Cerrar sesión");lock.setOnClickListener(v->{currentUser=null;access();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(50));lp.topMargin=dp(16);body.addView(lock,lp);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);}
    private void addHome(LinearLayout p,String a,String b,View.OnClickListener l){LinearLayout c=vertical();c.setPadding(dp(16),dp(8),dp(16),dp(8));c.setBackground(bg(Color.WHITE,17));c.setOnClickListener(l);c.addView(label(a,17,TEXT,true),new LinearLayout.LayoutParams(-1,dp(30)));c.addView(label(b,13,MUTED,false),new LinearLayout.LayoutParams(-1,dp(25)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(76));cp.topMargin=dp(10);p.addView(c,cp);}
    private void clients(){page("Clientes","Cartera de "+currentUser);EditText q=input("🔎  Buscar cualquier dato...");q.setBackground(bg(Color.WHITE,14));content.addView(q,new LinearLayout.LayoutParams(-1,dp(54)));Button add=primary("＋ Nueva póliza");add.setOnClickListener(v->addPolicy(null));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(50));ap.topMargin=dp(10);content.addView(add,ap);LinearLayout list=vertical();content.addView(list);Runnable render=()->{list.removeAllViews();JSONArray a=policies();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&match(p,q.getText().toString(),"Todas")){LinearLayout rr=row("👤 "+p.optString("holder"),p.optString("type")+"  ·  "+p.optString("number"));rr.setOnClickListener(v->detail(p));list.addView(rr);}}};q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){render.run();}public void afterTextChanged(android.text.Editable e){}});render.run();}
    private boolean match(JSONObject p,String q,String type){if(!type.equals("Todas")&&!type.equals(p.optString("type")))return false;String n=norm(q);if(n.isEmpty())return true;for(String k:new String[]{"type","number","expiry","holder","holderDni","phone","email","address"})if(norm(p.optString(k)).contains(n))return true;JSONArray m=p.optJSONArray("members");if(m!=null)for(int i=0;i<m.length();i++){JSONObject x=m.optJSONObject(i);if(x!=null){for(String k:new String[]{"name","dni","birth","relation","phone","address"})if(norm(x.optString(k)).contains(n))return true;}else if(norm(m.optString(i)).contains(n))return true;}return false;}
    private String norm(String s){return java.text.Normalizer.normalize(s==null?"":s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT);}
    private LinearLayout row(String a,String b){LinearLayout r=vertical();r.setPadding(dp(16),dp(7),dp(16),dp(7));r.setBackground(bg(Color.WHITE,14));r.addView(label(a,16,TEXT,true),new LinearLayout.LayoutParams(-1,dp(29)));r.addView(label(b,13,MUTED,false),new LinearLayout.LayoutParams(-1,dp(24)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(64));rp.topMargin=dp(9);r.setLayoutParams(rp);return r;}
    private void detail(JSONObject p){String msg="Titular: "+p.optString("holder")+"\nDNI/NIF: "+p.optString("holderDni")+"\nTeléfono: "+p.optString("phone")+"\nEmail: "+p.optString("email")+"\nDirección: "+p.optString("address")+"\nTipo: "+p.optString("type")+"\nPóliza: "+p.optString("number")+"\nVencimiento: "+p.optString("expiry");JSONArray m=p.optJSONArray("members");if(m!=null)for(int i=0;i<m.length();i++){JSONObject x=m.optJSONObject(i);if(x!=null)msg+="\n• "+x.optString("name")+" · "+x.optString("dni")+" · "+x.optString("relation");}new AlertDialog.Builder(this).setTitle("Ficha de póliza").setMessage(msg).setPositiveButton("Cerrar",null).setNegativeButton("Editar",(d,w)->addPolicy(p)).setNeutralButton("Compartir",(d,w)->confirmShare(p,msg)).show();}
    private void confirmShare(JSONObject p,String msg){new AlertDialog.Builder(this).setTitle("Compartir datos").setMessage("No se comparte nada automáticamente. Tú eliges si compartir y con qué aplicación.").setNegativeButton("Cancelar",null).setPositiveButton("Sí, compartir",(d,w)->shareText("RgaPro · "+p.optString("holder"),msg));}
    private void shareText(String title,String text){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_SUBJECT,title);i.putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(i,"Elegir aplicación para compartir"));}
    private void shareHelp(){new AlertDialog.Builder(this).setTitle("🛡 Privacidad").setMessage("Cada usuario tiene una cartera independiente. RgaPro no comparte datos por su cuenta. Solo se abre el selector de Android después de que tú confirmes el envío.").setPositiveButton("Entendido",null).show();}
    private void addPolicy(JSONObject old){LinearLayout box=vertical();box.setPadding(dp(18),0,dp(18),0);EditText holder=input("Titular"),dni=input("DNI / NIF"),phone=input("Teléfono"),email=input("Email"),address=input("Dirección"),number=input("Número de póliza"),expiry=input("Vencimiento AAAA-MM-DD");Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,Arrays.copyOfRange(TYPES,1,TYPES.length)));for(EditText e:new EditText[]{holder,dni,phone,email,address,number,expiry})box.addView(e,new LinearLayout.LayoutParams(-1,dp(50)));box.addView(type,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout members=vertical();box.addView(label("Personas aseguradas · Decesos",14,MUTED,true));box.addView(members);List<EditText[]> fields=new ArrayList<>();Button add=button("＋ Añadir persona");add.setOnClickListener(v->{EditText n=input("Nombre y apellidos"),dn=input("DNI/NIE"),dob=input("Fecha nacimiento"),rel=input("Parentesco"),ph=input("Teléfono"),ad=input("Domicilio");EditText[] fs={n,dn,dob,rel,ph,ad};fields.add(fs);for(EditText e:fs)members.addView(e,new LinearLayout.LayoutParams(-1,dp(46)));});box.addView(add,new LinearLayout.LayoutParams(-1,dp(48)));if(old!=null){holder.setText(old.optString("holder"));dni.setText(old.optString("holderDni"));phone.setText(old.optString("phone"));email.setText(old.optString("email"));address.setText(old.optString("address"));number.setText(old.optString("number"));expiry.setText(old.optString("expiry"));String typ=old.optString("type");int pos=Arrays.asList(Arrays.copyOfRange(TYPES,1,TYPES.length)).indexOf(typ);if(pos>=0)type.setSelection(pos);}AlertDialog d=new AlertDialog.Builder(this).setTitle(old==null?"Nueva póliza":"Editar póliza").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{JSONObject p=old==null?new JSONObject():new JSONObject(old.toString());p.put("id",old==null?UUID.randomUUID().toString():old.optString("id"));p.put("holder",holder.getText().toString());p.put("holderDni",dni.getText().toString());p.put("phone",phone.getText().toString());p.put("email",email.getText().toString());p.put("address",address.getText().toString());p.put("number",number.getText().toString());p.put("expiry",expiry.getText().toString());p.put("type",String.valueOf(type.getSelectedItem()));JSONArray mem=new JSONArray();for(EditText[] fs:fields){JSONObject person=new JSONObject();person.put("name",fs[0].getText().toString());person.put("dni",fs[1].getText().toString());person.put("birth",fs[2].getText().toString());person.put("relation",fs[3].getText().toString());person.put("phone",fs[4].getText().toString());person.put("address",fs[5].getText().toString());mem.put(person);}if(old!=null&&mem.length()==0&&old.optJSONArray("members")!=null)mem=old.optJSONArray("members");p.put("members",mem);JSONArray a=policies();if(old!=null){for(int i=0;i<a.length();i++){JSONObject z=a.optJSONObject(i);if(z!=null&&z.optString("id").equals(p.optString("id"))){a.put(i,p);break;}}}else a.put(p);savePolicies(a);d.dismiss();clients();}catch(Exception e){Toast.makeText(this,"No se pudo guardar",Toast.LENGTH_LONG).show();}}));d.show();}
    private void policiesPage(){page("Pólizas","Elige un tipo para ver solo lo que necesitas.");Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,TYPES));content.addView(type,new LinearLayout.LayoutParams(-1,dp(52)));LinearLayout list=vertical();content.addView(list);Runnable r=()->{list.removeAllViews();JSONArray a=policies();for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null&&match(p,"",String.valueOf(type.getSelectedItem()))){LinearLayout rr=row("📄 "+p.optString("holder"),p.optString("type")+"  · vence "+p.optString("expiry"));rr.setOnClickListener(v->detail(p));list.addView(rr);}}};type.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int p,long id){r.run();}});r.run();}
    private long daysTo(String s){try{Date d=new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(s);return (d.getTime()-System.currentTimeMillis())/(24L*60*60*1000);}catch(Exception e){return Long.MAX_VALUE;}}
    private void expiries(){page("Vencimientos","Te avisamos con tiempo para que no se te escape ninguna.");long[] marks={60,45,30,15};String[] names={"60 días","45 días","30 días","15 días"};JSONArray a=policies();boolean any=false;for(int m=0;m<marks.length;m++){LinearLayout sec=vertical();sec.setPadding(dp(14),dp(10),dp(14),dp(10));sec.setBackground(bg(Color.WHITE,16));TextView hd=label("⏰  "+names[m],17,m==0?GREEN:(m<3?ORANGE:Color.rgb(220,80,70)),true);sec.addView(hd,new LinearLayout.LayoutParams(-1,dp(34)));boolean group=false;for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);if(p!=null){long d=daysTo(p.optString("expiry"));if(d>=0&&d<=marks[m]&&(m==0||d>marks[m-1])){group=true;sec.addView(label("• "+p.optString("holder")+" · "+p.optString("type")+" · "+p.optString("expiry"),14,TEXT,false),new LinearLayout.LayoutParams(-1,dp(32)));}}}if(group){content.addView(sec);LinearLayout.LayoutParams sp=(LinearLayout.LayoutParams)sec.getLayoutParams();if(sp!=null)sp.topMargin=dp(9);any=true;}}if(!any)content.addView(label("🎉 No hay vencimientos en estos periodos.",15,MUTED,false));}
    private void settings(){page("Seguridad","Tus datos permanecen separados por usuario.");content.addView(label("👤 Usuario activo: "+currentUser,17,TEXT,true),new LinearLayout.LayoutParams(-1,dp(44)));Button add=primary("＋ Añadir usuario");add.setOnClickListener(v->createAdditionalUser());content.addView(add,new LinearLayout.LayoutParams(-1,dp(52)));Button sw=button("Cambiar de usuario");sw.setOnClickListener(v->{currentUser=null;access();});content.addView(sw,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(label("🛡 Compartición DESACTIVADA por defecto. Solo se inicia desde una ficha y exige confirmación.",14,MUTED,false),new LinearLayout.LayoutParams(-1,dp(70)));}
    private void createAdditionalUser(){final EditText name=input("Nombre de usuario"),a=pin("Clave de 6 dígitos"),b=pin("Repite la clave");LinearLayout box=vertical();box.setPadding(dp(18),0,dp(18),0);box.addView(name);box.addView(a);box.addView(b);new AlertDialog.Builder(this).setTitle("Nuevo usuario").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Crear",(d,w)->{String n=name.getText().toString().trim(),p=a.getText().toString();if(n.isEmpty()||!p.matches("\\d{6}")||!p.equals(b.getText().toString())){Toast.makeText(this,"Nombre y clave de 6 dígitos obligatorios",Toast.LENGTH_LONG).show();return;}try{JSONObject u=users();if(u.has(n)){Toast.makeText(this,"Ese usuario ya existe",Toast.LENGTH_SHORT).show();return;}JSONObject o=new JSONObject();byte[] s=new byte[16];new SecureRandom().nextBytes(s);o.put("pin_hash",Base64.encodeToString(derive(p,s),Base64.NO_WRAP));o.put("pin_salt",Base64.encodeToString(s,Base64.NO_WRAP));o.put("policies",new JSONArray());u.put(n,o);saveUsers(u);Toast.makeText(this,"Usuario creado con cartera independiente",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"No se pudo crear",Toast.LENGTH_LONG).show();}}).show();}
}
